WITH valid_accounts AS (SELECT * FROM accounts WHERE NOT (opened_date BETWEEN '2023-12-01' AND '2024-02-01' AND account_type = 'LOAN' AND customer_id IN (27, 35))), accounts_stats AS (SELECT account_type, MAX(balance) - MIN(balance) AS balance_range, AVG(balance) AS avg_balance FROM valid_accounts GROUP BY account_type) SELECT account_type, balance_range, avg_balance FROM accounts_stats WHERE balance_range < 44 ORDER BY balance_range DESC
